import XCTest

final class SendTests: XCTestCase {
    func testOpenRoomAndSend() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()

        let room = app.staticTexts["Weekend Plans"].firstMatch
        if room.waitForExistence(timeout: 20) {
            room.tap()
        }

        let composer = app.textViews["GrowingTextView"].firstMatch
        XCTAssertTrue(composer.waitForExistence(timeout: 15), "composer not found")
        composer.tap()
        composer.typeText("benchmark test")

        let send = app.buttons["Send"].firstMatch
        if send.waitForExistence(timeout: 5) {
            send.tap()
        } else {
            print("HIERARCHY:\n\(app.debugDescription)")
            XCTFail("send button not found")
            return
        }
        XCTAssertTrue(app.textViews.containing(NSPredicate(format: "value == %@", "benchmark test")).firstMatch.waitForExistence(timeout: 15), "message not shown")
    }
}
EOF
